import{_ as o,C as i,c as r,o as n,a9 as s,G as t}from"./chunks/framework.DuenUNqn.js";const k=JSON.parse('{"title":"🌈 收益限制","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"UltimateShop","link":"/wiki/UltimateShop"},{"title":"features","link":""},{"title":"🌈 收益限制","link":"/wiki/UltimateShop/features/earn-limit"}]},"headers":[],"relativePath":"wiki/UltimateShop/features/earn-limit.md","filePath":"wiki/UltimateShop/features/earn-limit.md"}'),m={name:"wiki/UltimateShop/features/earn-limit.md"};function p(c,e,h,u,_,d){const a=i("NolebaseGitContributors"),l=i("NolebaseGitChangelog");return n(),r("div",null,[e[0]||(e[0]=s('<h1 id="🌈-收益限制" tabindex="-1">🌈 收益限制 <a class="header-anchor" href="#🌈-收益限制" aria-label="Permalink to &quot;🌈 收益限制&quot;">​</a></h1><h2 id="economylimit" tabindex="-1">EconomyLimit <a class="header-anchor" href="#economylimit" aria-label="Permalink to &quot;EconomyLimit&quot;">​</a></h2><ul><li><p>EconomyLimit 是一个基于 Vault 经济接口的收益限制插件。 它通过字节码注入拦截经济插件的加钱方法，统计玩家获得的收益，并按照你配置的规则进行限制。</p></li><li><p>当玩家在某个规则周期内达到收益上限后，超出的金额不会直接消失，而是自动转入插件提供的虚拟银行。 玩家可以之后手动提取虚拟银行中的金额，但提取行为依然会计入收益统计，如果当前规则已经超限，则无法提取。</p></li><li><p>请注意：使用经济插件自身的 pay、give 等指令交易可能不会被插件检测到，因为这些经济插件内部操作可能不会经过 Vault。</p></li></ul><h3 id="插件支持" tabindex="-1">插件支持： <a class="header-anchor" href="#插件支持" aria-label="Permalink to &quot;插件支持：&quot;">​</a></h3><ul><li>多条收益规则同时生效</li><li>每条规则独立重置周期</li><li>条件化限额</li><li>虚拟银行存取</li><li>多语言显示</li><li>SQLite / MySQL / PostgreSQL / H2 数据库存储</li><li>Paper / Spigot 双平台文本兼容</li><li>display-name 使用 {lang:...} 按玩家语言动态显示</li></ul><p><a href="https://www.spigotmc.org/resources/economylimit-limit-your-player-earnings-by-anyway-daily-weekly-monthly-1-20-1-21-11.133458/" target="_blank" rel="noreferrer">点击下载</a></p>',6)),t(a),t(l)])}const y=o(m,[["render",p]]);export{k as __pageData,y as default};
